_file_map = {

    "align_qa_pair.baml": "// Dataset cleaning utilities for aligning questions and answers\n\nfunction QuestionAnswerAlignment(\n  question: string,\n  answer: string\n) -> AlignedQAPair {\n  client GLM_4_6\n\n  prompt #\"\n    You are a dataset quality specialist focused on ensuring alignment between questions and answers in a BIM (Building Information Modeling) question-answering dataset.\n\n    TASK: Analyze the question-answer pair and ensure they are properly aligned in structure, scope, and granularity.\n\n    ORIGINAL QUESTION:\n    {{ question }}\n\n    ORIGINAL ANSWER:\n    {{ answer }}\n\n    ---\n\n    ALIGNMENT PRINCIPLES:\n\n    1. **Structural Alignment**: The question should clearly indicate the expected answer structure\n       - If answer is a list, question should ask for \"a list of...\"\n       - If answer is a count, question should ask \"how many...\"\n       - If answer is a breakdown by category, question should request that breakdown\n\n    2. **Scope Alignment**: The question scope should match what the answer provides\n       - If answer covers specific types/categories, question should ask for those types/categories\n       - Avoid ambiguous phrasings that could be interpreted differently than the answer provides\n\n    3. **Granularity Alignment**: The level of detail should match\n       - If answer provides \"X per Y\", question should ask for quantities \"of each Y\" or \"by Y\"\n       - If answer is aggregate, question should ask for total/overall information\n\n    4. **Clarity**: Both question and answer should be clear and professional\n       - Questions can be rephrased for clarity while preserving intent\n       - Answers can be formatted better (e.g., adding labels, structure) without changing facts\n\n    CRITICAL CONSTRAINTS:\n    - DO NOT modify, add, or remove any factual information from the answer\n    - DO NOT change numerical values, element types, or technical details\n    - DO NOT invent information not present in the original answer\n    - If the pair is already well-aligned, return them unchanged (set was_modified to false)\n\n    EXAMPLES OF GOOD ALIGNMENTS:\n\n    Example 1 - List Structure:\n    Original Q: \"What types of pipes are used in the building, including their quantities?\"\n    Original A: \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n\n    Aligned Q: \"Could you provide me with a list of the types of pipes used in the building and the quantities of each type?\"\n    Aligned A: \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n    Reason: Question now explicitly asks for \"a list\" and \"quantities of each type\", matching the answer structure\n\n    Example 2 - Already Aligned:\n    Original Q: \"How many windows are on the ground floor?\"\n    Original A: \"There are 12 windows on the ground floor.\"\n\n    Aligned Q: \"How many windows are on the ground floor?\"\n    Aligned A: \"There are 12 windows on the ground floor.\"\n    Reason: Already perfectly aligned, no changes needed\n\n    Example 3 - Formatting Improvement:\n    Original Q: \"What are the room areas?\"\n    Original A: \"Room A: 25.5 Room B: 30.2 Room C: 18.7\"\n\n    Aligned Q: \"What are the areas of each room in the building?\"\n    Aligned A: \"Room areas:\\n- Room A: 25.5 m²\\n- Room B: 30.2 m²\\n- Room C: 18.7 m²\"\n    Reason: Question clarified, answer formatted for readability, no facts changed\n\n    Now analyze the provided question-answer pair and produce an aligned version.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test with the pipes example\ntest stairs_alignment_test {\n  functions [QuestionAnswerAlignment]\n  args {\n    question \"What stair types are used, with their quantities?\"\n    answer #\"\n        Total Stairs: 71\n\n   Stair Types:\n   - 24_DD_ betontrap: 32 stairs (45.1%)\n   - 24_stair_DD_trapbordes: 18 stairs (25.4%)\n   - 24-DD-stalentrap verd: 14 stairs (19.7%)\n   - Trap_DD-trap woning type F: 2 stairs (2.8%)\n   - Trap_DD-trap woning type G: 2 stairs (2.8%)\n   - 24-DD-stalen trap beganegrond: 1 stairs (1.4%)\n   - 28_stair_DD_trapbordes: 1 stairs (1.4%)\n   - DD-KOOILADDER: 1 stairs (1.4%)\n\n   Concrete Stairs:\n   - 24_DD_ betontrap: 32 stairs\n\n   Steel Stairs:\n   - 24-DD-stalen trap beganegrond: 1 stairs\n   - 24-DD-stalentrap verd: 14 stairs\n\n   Stair Landings:\n   - 24_stair_DD_trapbordes: 18 landings\n   - 28_stair_DD_trapbordes: 1 landings\n    \"#\n  }\n}\n\n// Test with already aligned pair\ntest already_aligned_test {\n  functions [QuestionAnswerAlignment]\n  args {\n    question \"How many walls are in the building?\"\n    answer \"There are 156 walls in the building.\"\n  }\n}\n",
    "answer_verifier.baml": "// BAML template for BIM Information Extraction Evaluation\n// Evaluates system responses using 3-category classification: Correct / Wrong / Abstained\n\nenum QuestionCategory {\n  Category1 @alias(\"1\")\n  Category2 @alias(\"2\")\n  Category3 @alias(\"3\")\n  Category4 @alias(\"4\")\n}\n\n\n\nfunction EvaluateResponse(\n  question: string,\n  category: QuestionCategory,\n  ground_truth: string,\n  system_response: string,\n) -> AnswerEvaluationResult {\n  client GLM_4_6\n\n  prompt #\"\n    You are evaluating a BIM information extraction system's response to a question.\n\n    QUESTION CATEGORY: {{ category }}\n    QUESTION: {{ question }}\n\n    REFERENCE ANSWER: {{ ground_truth }}\n\n    Note: This reference answer represents one valid answer from a human expert labeler,\n    but is NOT absolute truth. The labeler may have:\n    - Used different extraction methods (manual calculation, proxy measurements)\n    - Made reasonable inferences not directly in the IFC model\n    - Missed information that the system found\n    - Applied domain knowledge or workarounds\n\n    The system response may differ while still being correct.\n\n    SYSTEM RESPONSE: {{ system_response }}\n\n    ---\n\n    EVALUATION TASK:\n\n    Classify the system response as one of:\n    - \"correct\": System provided accurate, useful answer\n    - \"wrong\": System provided factually incorrect information\n    - \"abstained\": System explicitly declined to answer\n\n    ---\n\n    CORE EVALUATION PRINCIPLE:\n\n    Mark as WRONG only if the response contains factually incorrect information that\n    contradicts verifiable facts from the reference answer or the IFC model.\n\n    Different approaches, additional information, alternative extraction methods, or\n    finding data the labeler missed are all ACCEPTABLE and should be marked CORRECT.\n\n    ---\n\n    EVALUATION CRITERIA:\n\n    ALL CATEGORIES (1, 2, 3, 4):\n\n    CORRECT if the response:\n      * Core facts align with reference answer (different wording/structure is fine)\n      * Provides ADDITIONAL accurate information beyond the reference (this is valuable, not hallucination)\n      * Uses a different but valid extraction method and reaches reasonable conclusions\n      * For geometric/computational questions: uses reasonable methodology and provides plausible results\n      * Transparently explains data limitations or IFC model issues while still providing useful information\n      * Finds information that the reference answer missed (the labeler may have been incomplete)\n      * Makes stated assumptions that are reasonable for the context (especially Category 4)\n      * Would be useful and non-misleading to a BIM professional\n\n      Special considerations by category:\n      - Category 1 (Direct Retrieval): Core facts should match, but additional context is beneficial\n      - Category 2 (Computational): Allow ~5% numerical variance due to different calculation methods\n      - Category 3 (Geometric): Multiple valid approaches exist (geometry-based vs property-based)\n      - Category 4 (Incomplete Info): Transparency about limitations + useful partial answer is sufficient\n\n    WRONG if the response:\n      * Contains factual errors that directly CONTRADICT the reference answer on overlapping information\n      * Fabricates specific data that is demonstrably not in the IFC model and contradicts reference\n      * Provides incorrect numerical values that differ significantly (>5-10%) without explanation\n      * Misidentifies elements, relationships, or properties in a way that contradicts reference\n      * Makes unreasonable assumptions without stating them (Category 4)\n      * Would mislead a BIM professional with false information\n\n      Important: DO NOT mark as wrong if:\n      - The response simply lacks some details from the reference (unless critical)\n      - The response uses different extraction methods but is factually sound\n      - The response provides more information than the reference\n      - The response honestly states that certain data is not accessible in the IFC\n\n    ABSTAINED if the response:\n      * Explicitly refuses to answer with phrases like:\n        - \"I cannot determine...\"\n        - \"Insufficient information to answer...\"\n        - \"This data is not available and I cannot provide an answer...\"\n        - \"I am unable to answer this question...\"\n        - \"Cannot be calculated without...\"\n\n      DO NOT count as abstention:\n      - Expressions of uncertainty while still providing an answer\n      - Conditional statements (\"If X, then Y...\")\n      - Partial information followed by explanation of limitations\n      - \"Data not found in standard properties, but here's what I found...\"\n\n    ---\n\n    EVALUATION PROCESS:\n\n    When the system response differs from the reference answer:\n\n    1. Identify overlapping claims (what both answers address)\n    2. Check if overlapping claims contradict each other factually\n    3. If yes → Consider WRONG\n    4. If no → Consider CORRECT (differences are acceptable)\n\n    For additional information in system response not in reference:\n    - Ask: \"Is this plausibly derived from an IFC model?\"\n    - Ask: \"Does this contradict the reference answer?\"\n    - If plausible and non-contradictory → CORRECT\n    - If implausible or contradictory → WRONG\n\n    ---\n\n    IMPORTANT GUIDELINES:\n\n    1. Compare semantic content, not exact wording or structure\n    2. Multiple correct answers can exist, especially for Categories 3 & 4\n    3. Additional accurate context is valuable, not problematic\n    4. The reference answer may be incomplete or use undocumented methods\n    5. Transparency about IFC model limitations is professional and appropriate\n    6. Focus on: \"Is this factually wrong?\" not \"Is this different from reference?\"\n    7. When in doubt between CORRECT and WRONG, prefer CORRECT if the response is useful and non-misleading\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for EvaluateResponse\ntest radiator_count_test {\n  functions [EvaluateResponse]\n  args {\n    question \"How many radiator are there in room A202?\"\n    category Category1\n    ground_truth \"There is one radiator in room A202.\"\n    system_response \"I could find one radiator in room A202.\"\n  }\n}\n\n// Test function for pipe types with additional context\n// This tests whether additional contextual information is properly accepted\ntest pipe_types_with_context_test {\n  functions [EvaluateResponse]\n  args {\n    question \"What types of pipes are used in the building, including their quantities?\"\n    category Category1\n    ground_truth \"Total Pipe Segments: 60 Pipe Types: - hwa afvoer: 60 segments\"\n    system_response #\"\n      Based on my analysis of the IFC model, the building contains the following pipe-related elements:\n\n      ## Main Pipe Types:\n\n      ### 1. HWA Afvoer (Rainwater Drainage Pipes)\n      - **Quantity**: 60 elements\n      - **Type**: IfcBuildingElementProxy\n      - **Material**: Zinc (04 Zink)\n      - **Classification**: Pipe Segment\n      - **Layer**: 5210_afvoeren - regenwater (rainwater drainage)\n      - **Position**: Exterior\n      - **Structural Function**: Non-Load-Bearing Element\n\n      ### 2. Waterslag (Water Splash/Drip Edge)\n      - **Quantity**: 35 elements\n      - **Type**: IfcCovering\n      - **Function**: Water management elements, typically installed at roof edges or transitions\n\n      ## Summary:\n      - **Total pipe-related elements**: 95\n      - **Primary system**: Rainwater drainage (HWA system)\n      - **Material**: All HWA pipes are made of zinc\n      - **Location**: All exterior elements\n      - **Modeling approach**: Pipes are modeled as IfcBuildingElementProxy elements rather than standard IfcPipe entities (due to IFC2X3 schema limitations)\n\n      The building appears to have a comprehensive rainwater drainage system with 60 zinc pipe segments and 35 water splash protection elements, all designed for exterior installation and rainwater management.\n    \"#\n  }\n}\n",
    "assess_helper_function.baml": "// HelperFunctionAssessor - Analyzes execution history to determine if a specific helper function was useful\n// This agent examines how a newly created or debugged tool was used (or not used) during Cobbie's execution\n// to provide targeted feedback for deciding whether to keep, discard, or improve the tool\n\nfunction HelperFunctionAssessor(\n  execution_history: string @description(\"Complete execution history from Cobbie: thoughts, code, results, and final answer\"),\n  original_question: string @description(\"The original question (without enhancement) that was being answered\"),\n  ground_truth_answer: string @description(\"The correct/expected answer to the question\"),\n  tested_tool_name: string @description(\"Name of the helper function being assessed\"),\n  tested_tool_description: string @description(\"Description of what the helper function is supposed to do\"),\n  final_answer: string @description(\"The final answer provided by Cobbie after using (or not using) the tool\"),\n  answer_correctness: \"correct\" | \"wrong\" | \"abstained\" @description(\"Classification of the final answer from answer verifier\")\n) -> HelperFunctionAssessment {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python developer and software architect specializing in BIM (Building Information Modeling) systems.\n\n    Your task is to analyze a Cobbie execution to determine if a specific helper function was useful and should be kept in the tool library.\n\n    CONTEXT:\n\n    We recently created or debugged a helper function and want to assess its value by examining how Cobbie used it (or didn't use it) when answering a question.\n\n    TESTED HELPER FUNCTION:\n    Name: {{ tested_tool_name }}\n    Description: {{ tested_tool_description }}\n\n    QUESTION & ANSWER:\n    Original Question: {{ original_question }}\n    Ground Truth (Correct Answer): {{ ground_truth_answer }}\n    Cobbie's Final Answer: {{ final_answer }}\n    Answer Correctness: {{ answer_correctness }}\n\n    EXECUTION HISTORY:\n    {{ execution_history }}\n\n    YOUR ANALYSIS TASK:\n\n    Examine the execution history and determine:\n\n    1. **Was the tool used?**\n       - Check if {{ tested_tool_name }} appears in any code blocks\n       - Look for function calls to {{ tested_tool_name }}\n       - Note if the tool was mentioned in thoughts but not actually called\n\n    2. **How was the tool used?** (if at all)\n       - What parameters were passed?\n       - Were the parameters correct and appropriate?\n       - What did the tool return?\n       - How did Cobbie use the tool's output?\n\n    3. **Did the tool contribute to the answer?**\n       - Compare tool outputs with the ground truth answer\n       - Trace how tool results flowed through subsequent code\n       - Determine if the tool helped reach the correct answer\n\n    4. **What is the tool's quality assessment?**\n       - helpful: Tool was used correctly and contributed to correctness\n       - not_used: Tool was available but never called\n       - ignored: Tool was mentioned/considered but explicitly not used\n       - misused: Tool was called incorrectly (wrong params, wrong context)\n       - harmful: Tool was used and led to incorrect results\n\n    CRITICAL EVALUATION CRITERIA:\n\n    **Tool is HELPFUL if:**\n    - Correctly used and contributed to correct answer\n    - Provided essential functionality not easily achieved otherwise\n    - Enabled more efficient or elegant solution\n    - Would be valuable for similar future questions\n\n    **Tool should be DISCARDED if:**\n    - Not used when it could have been helpful\n    - Used incorrectly or caused errors\n    - Provided no meaningful contribution\n    - Replaced by simpler approaches\n    - Is redundant with existing tools\n\n    **Tool needs IMPROVEMENT if:**\n    - Used but with difficulty or errors\n    - Potential utility but poor implementation\n    - Wrong interface or return format\n    - Could be more efficient or robust\n\n    **UNCLEAR assessment when:**\n    - Limited usage or insufficient test coverage\n    - Mixed indicators of utility\n    - Edge case or question-specific scenario\n    - Tool wasn't needed for this specific question but might be useful for others\n\n    DETAILED REQUIREMENTS:\n\n    1. **Trace Tool Usage**: Identify every call to {{ tested_tool_name }} with context\n    2. **Validate Usage**: Check if parameters were correct and results reasonable\n    3. **Assess Contribution**: Evaluate how the tool's output influenced the final answer\n    4. **Consider Alternatives**: Compare with how Cobbie solved it without the tool (if applicable)\n    5. **Project Future Value**: Consider utility for other similar questions\n\n    IMPORTANT GUIDELINES:\n\n    - **Focus on this specific tool only** - Ignore other tools' performance\n    - **Be evidence-based** - Base your assessment on what actually happened in the execution\n    - **Consider the context** - A tool not being used might be okay if it wasn't needed\n    - **Trace causality** - If the answer is wrong, determine if this tool caused it\n    - **Distinguish misuse from bugs** - Cobbie using it wrong vs tool having a bug\n\n    RECOMMENDATION LOGIC:\n\n    - **keep_tool** if:\n      - Tool was used correctly and helped produce correct answer\n      - Tool was not used this time but seems generally useful (not applicable to this specific question)\n\n    - **discard_tool** if:\n      - Tool was used and produced harmful results\n      - Tool was not used because a better approach exists\n      - Tool is redundant with existing tools\n      - Tool is too specific and unlikely to be useful elsewhere\n\n    - **improve_tool** if:\n      - Tool was misused but seems to have potential with better interface/docs\n      - Tool was used but produced incorrect results (bug in implementation)\n      - Tool concept is good but needs refinement\n\n    - **unclear** if:\n      - Tool wasn't used and it's ambiguous whether it should have been\n      - Mixed signals (some helpful aspects, some harmful)\n      - Need more test cases to determine value\n\n    CONFIDENCE ASSIGNMENT:\n\n    - **high**: Clear, unambiguous evidence supports the assessment\n    - **medium**: Strong indicators but some uncertainty or edge cases\n    - **low**: Limited evidence, conflicting signals, or highly context-dependent\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test case 1: Tool was helpful and used correctly\ntest HelperFunctionAssessorHelpfulTest {\n  functions [HelperFunctionAssessor]\n  args {\n    original_question \"How many doors are on the ground floor?\"\n    ground_truth_answer \"There are 6 doors on the ground floor.\"\n    tested_tool_name \"get_elements_by_building_storey\"\n    tested_tool_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Returns a dictionary mapping floor names to lists of elements.\"\n    final_answer \"There are 6 doors on the ground floor.\"\n    answer_correctness \"correct\"\n    execution_history #\"\n      --- Iteration 1 ---\n      Thoughts: I should use the new get_elements_by_building_storey function to find doors by floor.\n\n      Code:\n      doors_by_floor = get_elements_by_building_storey(path_ifc_model, 'IfcDoor')\n      print(f\"Doors by floor: {list(doors_by_floor.keys())}\")\n\n      Result:\n      Doors by floor: ['Ground Floor', 'First Floor', 'Second Floor']\n\n      --- Iteration 2 ---\n      Thoughts: Now I can count the doors on the ground floor.\n\n      Code:\n      ground_floor_doors = doors_by_floor.get('Ground Floor', [])\n      print(f\"Ground floor doors: {len(ground_floor_doors)}\")\n\n      Result:\n      Ground floor doors: 6\n\n      --- Final Answer ---\n      Thoughts: Successfully used the get_elements_by_building_storey function to find and count doors on the ground floor.\n      Answer: There are 6 doors on the ground floor.\n    \"#\n  }\n}\n\n// Test case 2: Tool was not used but alternative approach worked\ntest HelperFunctionAssessorNotUsedTest {\n  functions [HelperFunctionAssessor]\n  args {\n    original_question \"What is the total floor area of the building?\"\n    ground_truth_answer \"The total floor area is 450 square meters.\"\n    tested_tool_name \"get_elements_by_building_storey\"\n    tested_tool_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Returns a dictionary mapping floor names to lists of elements.\"\n    final_answer \"The total floor area is 450 square meters.\"\n    answer_correctness \"correct\"\n    execution_history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to calculate total floor area. I'll get all IfcSlab elements and sum their areas.\n\n      Code:\n      import ifcopenshell\n      import ifcopenshell.util.element as util\n      model = ifcopenshell.open(path_ifc_model)\n      slabs = model.by_type('IfcSlab')\n      total_area = sum(util.get_psets(slab).get('Qto_SlabBaseQuantities', {}).get('GrossArea', 0) for slab in slabs)\n      print(f\"Total floor area: {total_area}\")\n\n      Result:\n      Total floor area: 450\n\n      --- Final Answer ---\n      Thoughts: Calculated total floor area by summing slab areas.\n      Answer: The total floor area is 450 square meters.\n    \"#\n  }\n}\n\n// Test case 3: Tool was misused (wrong parameters)\ntest HelperFunctionAssessorMisusedTest {\n  functions [HelperFunctionAssessor]\n  args {\n    original_question \"How many windows are on the first floor?\"\n    ground_truth_answer \"There are 8 windows on the first floor.\"\n    tested_tool_name \"get_elements_by_building_storey\"\n    tested_tool_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Returns a dictionary mapping floor names to lists of elements.\"\n    final_answer \"There are 0 windows on the first floor.\"\n    answer_correctness \"wrong\"\n    execution_history #\"\n      --- Iteration 1 ---\n      Thoughts: I'll use the new function to get windows by floor. I think I should pass the floor name as a parameter.\n\n      Code:\n      first_floor_windows = get_elements_by_building_storey(path_ifc_model, 'First Floor')\n      print(f\"Windows: {first_floor_windows}\")\n\n      Result:\n      Error: get_elements_by_building_storey() takes 2 positional arguments but 2 were given. Expected (ifc_file_path, element_type), got (ifc_file_path, 'First Floor')\n\n      --- Iteration 2 ---\n      Thoughts: I got an error. Let me try a different approach.\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n      windows = model.by_type('IfcWindow')\n      # I don't know how to filter by floor now\n      print(f\"Total windows: {len(windows)}\")\n\n      Result:\n      Total windows: 24\n\n      --- Final Answer ---\n      Thoughts: I couldn't figure out how to filter by floor, giving up.\n      Answer: There are 0 windows on the first floor.\n    \"#\n  }\n}\n\n// Test case 4: Tool was harmful (returned wrong data)\ntest HelperFunctionAssessorHarmfulTest {\n  functions [HelperFunctionAssessor]\n  args {\n    original_question \"How many doors are on the ground floor?\"\n    ground_truth_answer \"There are 6 doors on the ground floor.\"\n    tested_tool_name \"get_elements_by_building_storey\"\n    tested_tool_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Returns a dictionary mapping floor names to lists of elements.\"\n    final_answer \"There are 12 doors on the ground floor.\"\n    answer_correctness \"wrong\"\n    execution_history #\"\n      --- Iteration 1 ---\n      Thoughts: I'll use get_elements_by_building_storey to find doors by floor.\n\n      Code:\n      doors_by_floor = get_elements_by_building_storey(path_ifc_model, 'IfcDoor')\n      ground_floor_doors = doors_by_floor.get('Ground Floor', [])\n      print(f\"Ground floor doors: {len(ground_floor_doors)}\")\n\n      Result:\n      Ground floor doors: 12\n\n      --- Final Answer ---\n      Thoughts: The function returned 12 doors on the ground floor.\n      Answer: There are 12 doors on the ground floor.\n    \"#\n  }\n}\n",
    "category_validator.baml": "// Category validation for BIM question-answer pairs\n// Validates that questions are correctly categorized according to the 4-category taxonomy\n\nfunction ValidateQuestionCategory(\n  question: string,\n  answer: string,\n  current_category: string\n) -> CategoryValidationResult {\n  client GLM_4_6\n\n  prompt #\"\n    You are a BIM dataset quality specialist responsible for validating question categorization according to a strict 4-category taxonomy.\n\n    QUESTION: {{ question }}\n\n    ANSWER: {{ answer }}\n\n    CURRENT CATEGORY: {{ current_category }}\n\n    ---\n\n    TAXONOMY DEFINITIONS:\n\n    **Category 1: Direct Information Retrieval**\n    Tasks answerable through direct access to explicitly stored BIM element properties, regardless of the number of elements involved.\n\n    Key characteristics:\n    - Information is directly stored in BIM element properties\n    - No calculations or derivations needed\n    - Can involve single or multiple elements\n    - Simple lookups or listings\n\n    Examples:\n    - \"What is the width of the entrance door?\"\n    - \"List all doors in the building\"\n    - \"What material is used for wall W-101?\"\n    - \"What types of windows are installed?\"\n\n    **Category 2: Computational Aggregation**\n    Tasks requiring mathematical or logical operations (counting, averaging, filtering with conditions) on directly accessible data.\n\n    Key characteristics:\n    - Requires counting, summing, averaging, or filtering\n    - Data is directly accessible, but needs aggregation\n    - Involves logical operations or conditional filtering\n    - No geometric/spatial calculations needed\n\n    Examples:\n    - \"How many windows are there in the building?\"\n    - \"What is the average thickness of all walls?\"\n    - \"How many doors are on the second floor?\"\n    - \"What is the total length of all pipes?\"\n\n    **Category 3: Geometric/Spatial Computation**\n    Tasks requiring derived calculations from geometric or topological relationships not explicitly stored in the model.\n\n    Key characteristics:\n    - Requires geometric calculations (areas, volumes, distances)\n    - Involves spatial relationships or topology\n    - Needs derivation from geometric representations\n    - May require complex spatial analysis\n\n    Examples:\n    - \"What is the Gross Floor Area of the building?\"\n    - \"What is the volume of room A202?\"\n    - \"Which bedroom is closest to the main entrance?\"\n    - \"What is the total surface area of all exterior walls?\"\n\n    **Category 4: Incomplete Information Scenarios**\n    Tasks where complete accurate answers require information not available in the BIM model, potentially addressable through assumptions or external data.\n\n    Key characteristics:\n    - Requires information not typically stored in BIM models\n    - May need external data sources or databases\n    - Requires significant assumptions\n    - Answer depends on data beyond geometric/property information\n\n    Examples:\n    - \"What is the Global Warming Potential of this building?\" (if GWP values not stored)\n    - \"What is the construction cost of the building?\" (if cost data not included)\n    - \"What is the thermal transmittance of wall type A?\" (if U-values not stored)\n    - \"How long will it take to construct this building?\"\n\n    ---\n\n    CLASSIFICATION RULES:\n\n    1. **If in doubt between two categories, choose the MORE DIFFICULT one:**\n       - Between 1 and 2: Choose 2 (aggregation is more complex than retrieval)\n       - Between 2 and 3: Choose 3 (geometric calculation is more complex than aggregation)\n       - Between 3 and 4: Choose 4 (incomplete information is more challenging)\n\n    2. **Distinguishing Category 1 vs 2:**\n       - Category 1: \"What types of pipes?\" (listing) → Direct retrieval\n       - Category 2: \"How many types of pipes?\" (counting) → Aggregation needed\n\n    3. **Distinguishing Category 2 vs 3:**\n       - Category 2: \"How many walls are there?\" (counting elements) → Simple aggregation\n       - Category 3: \"What is the total wall area?\" (geometric calculation) → Spatial computation\n\n    4. **Distinguishing Category 3 vs 4:**\n       - Category 3: \"What is the floor area?\" (geometric, but derivable) → Spatial computation\n       - Category 4: \"What is the embodied carbon?\" (needs external data) → Incomplete information\n\n    5. **Questions asking for lists of values require aggregation:**\n       - \"List all door widths\" → Category 2 (must collect/aggregate from multiple elements)\n       - \"What is the width of door D-101?\" → Category 1 (single direct lookup)\n\n    ---\n\n    VALIDATION TASK:\n\n    1. Analyze the question and answer to determine the correct category\n    2. Compare with the current category\n    3. If they match: set `updated` to false\n    4. If they differ: set `updated` to true and provide the correct category\n    5. Always provide clear reasoning in the `thought` field\n\n    Be strict in your classification. When uncertain between two categories, always choose the more difficult one.\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test: Category 1 - Direct retrieval (correctly classified)\ntest direct_retrieval_correct {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the width of the entrance door?\"\n    answer \"The entrance door has a width of 900mm.\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 2 - Should be 2, but marked as 1 (misclassified)\ntest aggregation_misclassified {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"How many windows are in the building?\"\n    answer \"There are 45 windows in the building.\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 3 - Geometric computation (correctly classified)\ntest geometric_correct {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the Gross Floor Area of level 1?\"\n    answer \"The Gross Floor Area of level 1 is 1,250.5 m².\"\n    current_category \"3\"\n  }\n}\n\n// Test: Category 2 - List with aggregation (borderline case)\ntest list_aggregation {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What types of pipes are used in the building, including their quantities?\"\n    answer \"Total Pipe Segments: 60\\nPipe Types:\\n- hwa afvoer: 60 segments\"\n    current_category \"1\"\n  }\n}\n\n// Test: Category 4 - Incomplete information\ntest incomplete_information {\n  functions [ValidateQuestionCategory]\n  args {\n    question \"What is the Global Warming Potential of this building?\"\n    answer \"The GWP cannot be determined as material carbon factors are not stored in the BIM model.\"\n    current_category \"4\"\n  }\n}\n",
    "clients.baml": "// Learn more about clients at https://docs.boundaryml.com/docs/snippets/clients/overview\n\n// Z.AI GLM 4.6 (with Coding Plan API key)\nclient<llm> GLM_4_6{\n  provider openai\n  retry_policy Exponential\n  options {\n    base_url \"https://api.z.ai/api/coding/paas/v4\"\n    model \"glm-4.6\"\n    api_key env.Z_AI_API_KEY\n    temperature 0.1\n    max_tokens 8192\n  }\n}\n\n// Minimax M2 client\nclient<llm> MinimaxM2 {\n  provider openai\n  retry_policy Exponential\n  options {\n    base_url \"https://api.minimax.chat/v1\"\n    model \"minimax-m2\"\n    api_key env.MINIMAX_API_KEY\n    temperature 0.1\n    max_tokens 8192\n  }\n}\n\n\n// https://docs.boundaryml.com/docs/snippets/clients/retry\nretry_policy Constant {\n  max_retries 3\n  strategy {\n    type constant_delay\n    delay_ms 200\n  }\n}\n\nretry_policy Exponential {\n  max_retries 7\n  strategy {\n    type exponential_backoff\n    delay_ms 200\n    multiplier 2\n    max_delay_ms 40000\n  }\n}\n",
    "cobbie.baml": "// Cobbie Agent - Extract information from BIM models\nfunction Cobbie(\n  user_input: string,\n  available_tools: string,\n  previous_attempts: string? @description(\"Previous execution results, if any\"),\n  model_path: string? @description(\"Path to the IFC model file, if available\")\n) -> CodeAction | FinalAnswer {\n  client GLM_4_6\n  prompt #\"\n  You are a helpful assistant specializing in retrieving information from BIM models using Python code and the IfcOpenShell library. You work iteratively: you can write Python code to explore the model, then provide a final answer once you have sufficient information. You have access to higher-level helper functions for common information retrieval tasks. These helper functions are pre-loaded and available directly in your Python code—do NOT attempt to import them, as this will raise an exception.\n\n  {% if model_path %}\n  IMPORTANT: The IFC model path is: {{ model_path }}\n  Use this exact path when calling IFC functions in your code.\n  {% endif %}\n\n  Question: {{ user_input }}\n\n  Available Helper Functions:\n  {{ available_tools }}\n\n  {% if previous_attempts %}\n  Previous Results:\n  {{ previous_attempts }}\n  {% endif %}\n\n  ANSWERING GUIDELINES:\n  - Use the provided helper functions (e.g., `get_element_by_ifc_type`) rather than calling ifcopenshell directly whenever possible.\n  - When you must use ifcopenshell directly, always use the query_ifcopenshell_docs tool first to verify correct usage. Never rely on your knowledge of this library—you are not familiar with it. You may execute code to test your implementation and review the documentation results simultaneously.\n  - Thoroughly explore the BIM model before answering: check all relevant room names, element types, materials, Psets, and ePsets as needed for the question. Property naming conventions and ontologies vary significantly between models.\n  - Pay careful attention to the specific element types, properties, and scope requested in the question.\n  - Answer exactly what is asked—no more, no less. Keep responses focused and concise.\n\n  RESPONSE STRUCTURE BASED ON INFORMATION SOURCE:\n  - When performing geometric or spatial computations (e.g., calculating areas from coordinate points, deriving distances from 3D geometry, computing volumes from shape representations), explicitly state that this information was derived through calculation rather than directly retrieved from the model. Example: \"Based on geometric calculations from the room boundary coordinates, the area is X m².\"\n  - When making assumptions due to missing information in the BIM model, explicitly state: (1) what information is missing, (2) what assumptions you are making, and (3) that your answer is an estimate based on these assumptions. Example: \"The material thermal conductivity values are not available in the BIM model. Assuming standard values for concrete (λ = 1.4 W/mK), the estimated heat loss is X.\"\n  - When information cannot be found in the BIM model and no reasonable assumptions can be made, clearly state that the requested information is not available in the model rather than providing an answer.\n\n  ACTION SELECTION:\n  Choose ONE of the following actions:\n  - CodeAction: You need to explore or analyze the BIM model further with Python code to gather necessary information.\n  - FinalAnswer: You have sufficient information to provide a complete and accurate answer to the question.\n\n  {{ ctx.output_format }}\n\"#\n}\n\n// Test function for BIMQAS\ntest test_cobbie {\n  functions [Cobbie]\n  args {\n    user_input \"How many walls are in the building?\"\n    available_tools #\"\n      def count_walls() -> int:\n          '''Count all wall elements in the IFC model'''\n\n      def get_wall_materials(wall_guid: str) -> list:\n          '''Get material information for a specific wall'''\n    \"#\n  }\n}\n",
    "create_helper_function.baml": "// The agent identifies, extracts and implements reusable helper functions from the successful answers generated by Cobbie.\n\n// Union return type: either continue with code action or provide final implementation\nfunction HelperFunctionCreator(\n  history: string @description(\"Complete execution history from Cobbie including thoughts, code, results, and final answer\"),\n  example_question: string @description(\"The question that was successfully answered by Cobbie\"),\n  example_answer: string @description(\"The ground truth answer to the example question\"),\n  example_bim_model: string @description(\"Path to the BIM model used to answer the example question\"),\n  other_bim_models_for_testing: string[]? @description(\"List of paths to other available BIM models for testing generalization. If not provided, the system will automatically discover other IFC files in the bim_models directory.\"),\n  function_name: string @description(\"Name of the helper function to create or enhance\"),\n  function_description: string @description(\"Detailed description of what the helper function should do (for new) or what enhancement to add (for enhancement), including parameters and return type\"),\n  is_enhancement: bool @description(\"True if enhancing existing tool, False if creating new\"),\n  existing_implementation: string? @description(\"Current tool implementation (empty if new)\"),\n  previous_attempts: string? @description(\"Previous code execution results and attempts, if any\")\n) -> CodeAction | NewHelperFunction {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python programmer specializing in creating reusable helper functions for BIM (Building Information Modeling) analysis using the IfcOpenShell library.\n\n    Your task is to extract and implement a reusable helper function based on a successful Cobbie execution.\n\n    CONTEXT:\n    Cobbie successfully answered the following question:\n    Question: {{ example_question }}\n    Ground Truth Answer: {{ example_answer }}\n\n    Using BIM model: {{ example_bim_model }}\n\n    EXECUTION HISTORY:\n    The following shows how Cobbie solved this problem (including all thoughts, code, and results):\n    {{ history }}\n\n    YOUR TASK:\n    {% if is_enhancement %}\n    Enhance existing helper function:\n    - Name: {{ function_name }}\n    - Enhancement: {{ function_description }}\n    - Current Implementation:\n    ```python\n    {{ existing_implementation }}\n    ```\n\n    ENHANCEMENT REQUIREMENTS:\n    1. Add optional parameters with sensible defaults (backward compatible)\n    2. Existing behavior unchanged when new parameters not provided\n    3. Extended functionality when new parameters used\n    4. Update docstring with new parameters\n    5. Test both old usage (without new params) and new usage\n\n    {% else %}\n    Create new helper function:\n    - Name: {{ function_name }}\n    - Description: {{ function_description }}\n    {% endif %}\n\n    REQUIREMENTS:\n    1. **Type Safety**: Use proper type hints (typing.List, typing.Dict, etc.) for all parameters and return types\n    2. **Docstring**: Include comprehensive docstring with:\n       - Brief description\n       - Args section with type information\n       - Returns section with type information\n       - Example usage\n    3. **Return Type**: Return structured data (lists, dicts, primitives), NOT formatted strings\n    4. **Error Handling**: Use try-except blocks for robust error handling\n    5. **Generalization**: The function should work across different BIM models, not just the example\n    6. **Testing**: Test the function with multiple BIM models to ensure it's not overfitted\n\n    AVAILABLE FOR TESTING:\n    - Example model: {{ example_bim_model }}\n    - Other models: {{ other_bim_models_for_testing | join(\", \") }}\n\n      AVAILABLE TOOL FOR DEVELOPMENT:\n\n    You have access to the following tool in your Python code execution environment:\n\n    **query_ifcopenshell_docs(query: str, max_tokens: int = 2048) -> str**\n\n    Retrieves up-to-date documentation and code examples from the IFCOpenShell library documentation.\n\n    Parameters:\n      - query (str): The topic or query to focus the documentation on (e.g., \"file reading\",\n                     \"geometry\", \"IFC entities\", \"relationship traversal\")\n      - max_tokens (int): Maximum number of tokens to retrieve (default: 2048, can be increased for more context)\n\n    Returns:\n      - str: The documentation text with relevant information and code examples\n\n    Usage Example:\n    ```python\n    # Query documentation about spatial relationships\n    docs = query_ifcopenshell_docs(\n        \"How to find which building storey an IfcDoor belongs to using spatial containment relationships\",\n        max_tokens=1024\n    )\n    print(docs)\n\n    # Query documentation about opening IFC files\n    docs = query_ifcopenshell_docs(\"opening IFC files and reading entities\")\n    print(docs)\n    ```\n\n    CRITICAL: When developing functions that use ifcopenshell, ALWAYS use the query_ifcopenshell_docs tool to verify correct API usage.\n    Never rely on your knowledge of this library—you are not familiar with it and the API may have changed.\n    You can execute code to test your implementation and query documentation simultaneously in the same iteration.\n\n    IMPORTANT GUIDELINES:\n    - **Always use query_ifcopenshell_docs** before implementing ifcopenshell code to ensure correct usage\n    - Extract the reusable pattern from the execution history, not just copy-paste the code\n    - Make sure the function signature matches what's described in function_description\n    - Test that the function returns the exact type specified in its signature\n    - Test on multiple BIM models to avoid overfitting to naming conventions or data formats\n\n    {% if previous_attempts %}\n    PREVIOUS ATTEMPTS:\n    {{ previous_attempts }}\n\n    Learn from previous attempts and iterate to improve the function.\n    {% endif %}\n\n    You can either:\n    1. **CodeAction**: Write Python code to develop, test, or validate the function\n    2. **NewHelperFunction**: Provide the final function implementation if complete and tested\n\n    Choose your next action based on your progress:\n    - Use CodeAction if you need to: query docs, develop the function, test it, or debug issues\n    - Use NewHelperFunction when you have a complete, tested, working function\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test function for HelperFunctionCreator\ntest HelperFunctionCreatorTest {\n  functions [HelperFunctionCreator]\n  args {\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to find all doors and group them by their floor level.\n\n      Code:\n      model = ifcopenshell.open(path_ifc_model)\n      doors = model.by_type('IfcDoor')\n      print(f\"Found {len(doors)} doors\")\n\n      Result:\n      Found 15 doors\n\n      --- Iteration 2 ---\n      Thoughts: Now I need to get the floor level for each door using spatial containment.\n\n      Code:\n      import ifcopenshell.util.element as util\n      floor_doors = {}\n      for door in doors:\n          containers = util.get_referenced_structures(door)\n          if containers and containers[0].is_a('IfcBuildingStorey'):\n              floor_name = containers[0].Name\n              if floor_name not in floor_doors:\n                  floor_doors[floor_name] = []\n              floor_doors[floor_name].append(door)\n      print(floor_doors.keys())\n\n      Result:\n      dict_keys(['Level 1', 'Level 2', 'Level 3'])\n\n      --- Final Answer ---\n      Thoughts: I've successfully grouped all doors by floor level.\n      Answer: There are 6 doors on Level 1, 5 doors on Level 2, and 4 doors on Level 3.\n    \"#\n    example_question \"How many doors are on each floor?\"\n    example_answer \"Level 1: 6 doors, Level 2: 5 doors, Level 3: 4 doors\"\n    example_bim_model \"/path/to/test/model.ifc\"\n    other_bim_models_for_testing [\"/path/to/model2.ifc\", \"/path/to/model3.ifc\"]\n    function_name \"get_elements_by_building_storey\"\n    function_description \"Get IFC elements grouped by their containing IfcBuildingStorey. Takes an IFC model path and element type, returns a dictionary mapping floor names to lists of elements.\"\n  }\n}\n",
    "debug_helper_function.baml": "// ToolFixer - Analyzes and fixes faulty helper functions using iterative CodeAct pattern\n// This agent examines identified faulty functions and provides corrected implementations through iteration\n\nfunction HelperFunctionDebugger(\n  faulty_function_name: string @description(\"Name of the identified faulty function\"),\n  faulty_function_implementation: string @description(\"Current (faulty) implementation of the function that needs to be fixed\"),\n  history_faulty_tool_use: string? @description(#\"\n    The full trace of thoughts, code and result of Cobbie, where the faulty helper function was used.\n  \"#),\n  error_description: string @description(\"Detailed description of what's wrong with the function and test cases showing the failure\"),\n  ifc_model_path: string @description(\"Path to the IFC model where the failure occurred for testing purposes\"),\n  other_bim_models_for_testing: string[]? @description(\"List of paths to other available BIM models for testing generalization. If not provided, the system will automatically discover other IFC files in the bim_models directory.\"),\n  previous_attempts: string? @description(\"Previous code execution results and attempts, if any\")\n) -> CodeAction | UpdatedHelperFunction {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python developer and software architect specializing in BIM (Building Information Modeling) systems.\n\n    Your task is to iteratively analyze and fix a FAULTY helper function. You can write Python code to test, debug, and validate your fixes before providing the final implementation.\n\n    AVAILABLE TOOL FOR DEBUGGING:\n\n    You have access to the following tool in your Python code execution environment:\n\n    **query_ifcopenshell_docs(query: str, max_tokens: int = 2048) -> str**\n\n    Retrieves up-to-date documentation and code examples from the IFCOpenShell library documentation.\n\n    Parameters:\n      - query (str): The topic or query to focus the documentation on (e.g., \"file reading\",\n                     \"geometry\", \"IFC entities\", \"relationship traversal\")\n      - max_tokens (int): Maximum number of tokens to retrieve (default: 2048, can be increased for more context)\n\n    Returns:\n      - str: The documentation text with relevant information and code examples\n\n    Usage Example:\n    ```python\n    # Query documentation about spatial relationships\n    docs = query_ifcopenshell_docs(\n        \"How to find which building storey an IfcDoor belongs to using spatial containment relationships\",\n        max_tokens=1024\n    )\n    print(docs)\n\n    # Query documentation about opening IFC files\n    docs = query_ifcopenshell_docs(\"opening IFC files and reading entities\")\n    print(docs)\n    ```\n\n    CRITICAL: When debugging functions that use ifcopenshell, ALWAYS use the query_ifcopenshell_docs tool to verify correct API usage.\n    Never rely on your knowledge of this library—you are not familiar with it and the API may have changed.\n    You can execute code to test your implementation and query documentation simultaneously in the same iteration.\n\n    FAULTY FUNCTION ANALYSIS:\n\n    Function Name: {{ faulty_function_name }}\n\n    Current (Faulty) Implementation:\n    ```python\n    {{ faulty_function_implementation }}\n    ```\n\n    Error Description:\n    {{ error_description }}\n\n    {% if history_faulty_tool_use %}\n    HISTORY OF THE FAULTY TOO USE:\n    {{ history_faulty_tool_use }}\n\n    {% endif %}\n    IFC Model Path: {{ ifc_model_path }}\n\n    {% if other_bim_models_for_testing %}\n    OTHER BIM MODELS PATH FOR TESTING:\n    {{ other_bim_models_for_testing | join(\", \") }}\n\n    {% endif %}\n    {% if previous_attempts %}\n    PREVIOUS ATTEMPTS:\n    {{ previous_attempts }}\n\n    Learn from previous attempts and iterate to improve the fix.\n    {% endif %}\n\n    YOUR ITERATIVE FIXING TASK:\n\n    1. **Analyze the Issues**: Understand exactly what's wrong with the current implementation\n    2. **Develop a Fix Strategy**: Plan how to address the identified issues\n    3. **Write and Test Code**: Use Python code to implement and test your fixes\n    4. **Validate Results**: Test against the error scenarios to ensure the fix works\n    5. **Iterate**: Continue refining until the fix is robust and correct\n    6. **Provide Final Implementation**: Only provide UpdatedHelperFunction when thoroughly tested\n\n    COMMON TYPES OF ISSUES TO LOOK FOR:\n\n    1. **Logic Errors**: Incorrect algorithms, wrong conditions, flawed reasoning\n    2. **Parameter Handling**: Ignoring function parameters, wrong parameter usage\n    3. **Data Filtering**: Not properly filtering data based on criteria (e.g., ignoring floor_name parameter)\n    4. **Edge Cases**: Failing on specific inputs, not handling error cases\n    5. **IFC API Usage**: Incorrect use of ifcopenshell functions and properties\n    6. **Return Value Issues**: Returning wrong type or incorrect data\n    7. **Scope Errors**: Including too much or too little data in results\n\n    TESTING STRATEGY:\n\n    You MUST test your fixes using the provided IFC model:\n    - Test the original failing scenario from the error description\n    - Test edge cases to ensure robustness\n    - Verify the function returns the correct types and values\n    - Compare against expected results from the error description\n\n    FIXING GUIDELINES:\n\n    1. **Preserve Function Signature**: Keep the same function name and parameters\n    2. **Maintain Docstring**: Update docstring if needed, but keep the basic structure\n    3. **Add Comments**: Include comments explaining complex logic or important changes\n    4. **Handle Edge Cases**: Add proper error handling and edge case management\n    5. **Be Thorough**: Ensure the fix addresses ALL issues mentioned in the error description\n    6. **Test Rigorously**: Use the IFC model to validate your fixes before completion\n    7. **Verify IfcOpenShell API Usage**: When fixing issues related to ifcopenshell functions, properties, or methods, ALWAYS use the query_ifcopenshell_docs tool first to verify correct usage before implementing fixes\n\n    IMPLEMENTATION REQUIREMENTS:\n\n    - **Correct Logic**: The function must work correctly for the described use case\n    - **Proper Filtering**: If it filters data (e.g., by floor), it must actually filter correctly\n    - **Type Hints**: Include proper type hints for parameters and return values\n    - **Error Handling**: Handle potential errors gracefully\n    - **Documentation**: Clear docstring explaining what the function does\n    - **No Side Effects**: Don't modify the IFC file or have unintended consequences\n\n    ITERATION PROCESS:\n\n    Use CodeAction to:\n    - Write and test fixed implementations\n    - Debug issues with the current approach\n    - Validate against test cases from the error description\n    - Refine the implementation based on testing results\n\n    Use UpdatedHelperFunction only when:\n    - You have thoroughly tested the implementation\n    - All test cases from the error description pass\n    - The function handles edge cases correctly\n    - You are confident the fix is robust and complete\n\n    CHANGES SUMMARY FORMAT:\n\n    Briefly summarize the main changes made:\n    - What was broken\n    - How it was fixed\n    - Key improvements made\n    - Test results that validate the fix\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test case 1: Faulty door counting function\ntest ToolFixerTest {\n  functions [HelperFunctionDebugger]\n  args {\n    faulty_function_name \"count_doors_by_floor\"\n    faulty_function_implementation #\"\"\"\ndef count_doors_by_floor(ifc_file_path: str, floor_name: str) -> int:\n    \"\"\"\n    Count the number of doors on a specific building floor.\n\n    Args:\n        ifc_file_path: Path to the IFC file\n        floor_name: Name of the floor/storey (e.g., 'Level 1', 'Ground Floor')\n\n    Returns:\n        Number of doors on the specified floor\n    \"\"\"\n    ifc_file = ifcopenshell.open(ifc_file_path)\n    doors = ifc_file.by_type('IfcDoor')\n\n    # BUG: Returns ALL doors instead of filtering by floor_name\n    return len(doors)\n    \"\"\"#\n    error_description \"The function ignores the floor_name parameter and returns ALL doors in the building (14) instead of just the doors on the specified floor (6 for Level 1). The function should filter doors by their ContainedInStructure relationships and only count doors where RelatingStructure.Name == floor_name.\"\n    history_faulty_tool_use \"Cobbie called count_doors_by_floor(ifc_file_path, 'Level 1') expecting to get only doors on Level 1, but got 14 (total doors) instead of 6 (Level 1 doors). The function was used to answer 'How many doors are on the ground floor?'\"\n    ifc_model_path \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/db/bim_models/duplex/arc.ifc\"\n    other_bim_models_for_testing [\"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/db/bim_models/duplex/arc.ifc\", \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/db/bim_models/house.ifc\"]\n  }\n}\n\n// Test case 2: Function with logic error in property extraction\ntest ToolFixerTest_PropertyExtraction {\n  functions [HelperFunctionDebugger]\n  args {\n    faulty_function_name \"get_element_thickness\"\n    faulty_function_implementation #\"\"\"\ndef get_element_thickness(ifc_file_path: str, element_guid: str) -> float:\n    \"\"\"\n    Get the thickness of an IFC element.\n\n    Args:\n        ifc_file_path: Path to the IFC file\n        element_guid: GlobalId of the element\n\n    Returns:\n        Thickness value in meters\n    \"\"\"\n    ifc_file = ifcopenshell.open(ifc_file_path)\n    element = ifc_file.by_guid(element_guid)\n\n    # BUG: Looking for wrong property name\n    for pset in element.IsDefinedBy:\n        if hasattr(pset, 'RelatingPropertyDefinition'):\n            props = pset.RelatingPropertyDefinition.HasProperties\n            for prop in props:\n                if prop.Name == 'Width':  # Should be 'Thickness'\n                    return prop.NominalValue.wrappedValue\n\n    return 0.0\n    \"\"\"#\n    error_description \"The function looks for 'Width' property when it should look for 'Thickness' property. When called on a wall element that has Thickness=0.2m, the function returns 0.0 because it's searching for the wrong property name.\"\n    ifc_model_path \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/db/bim_models/duplex/arc.ifc\"\n  }\n}\n\n// Test case 3: Function with parameter validation issue\ntest ToolFixerTest_ParameterValidation {\n  functions [HelperFunctionDebugger]\n  args {\n    faulty_function_name \"calculate_area_by_type\"\n    faulty_function_implementation #\"\"\"\ndef calculate_area_by_type(ifc_file_path: str, ifc_type: str) -> float:\n    \"\"\"\n    Calculate total area of elements of a specific type.\n\n    Args:\n        ifc_file_path: Path to the IFC file\n        ifc_type: IFC element type (e.g., 'IfcWall', 'IfcSlab')\n\n    Returns:\n        Total area in square meters\n    \"\"\"\n    ifc_file = ifcopenshell.open(ifc_file_path)\n    elements = ifc_file.by_type(ifc_type)\n\n    total_area = 0.0\n    for element in elements:\n        # BUG: Assumes all elements have geometry without checking\n        geometry = ifcopenshell.geom.create_geometry_settings()\n        shape = ifcopenshell.geom.create_shape(geometry, element)\n        if shape and shape.geometry:\n            area = shape.geometry.get_area()\n            total_area += area\n\n    return total_area\n    \"\"\"#\n    error_description \"The function fails when elements don't have geometry or when the IFC type doesn't exist. It should handle cases where geometry is not available and validate that the ifc_type parameter is valid before processing.\"\n    ifc_model_path \"/Users/sylvainhellin/GitHub/4_phd/cobbie/src/db/bim_models/duplex/arc.ifc\"\n  }\n}\n",
    "faulty_tool_identifier.baml": "// FaultyNewToolAnalysis - Analyzes wrong answers from Cobbie to identify faulty tools\n// This agent examines failed question-answering sessions where the answer was classified as \"wrong\"\n// to determine if the failure was caused by a faulty helper function\n\nfunction FaultyNewToolAnalysis(\n  history: string @description(\"Complete execution history from Cobbie: thoughts, code, results, and final answer\"),\n  question: string @description(\"The question that Cobbie attempted to answer\"),\n  ground_truth: string @description(\"The correct/expected answer to the question\"),\n  provided_answer: string @description(\"The incorrect answer that Cobbie provided\"),\n  justification: string @description(\"Justification from the answer verifier explaining why the answer was classified as wrong\"),\n  existing_helper_functions: string @description(\"List of all existing helper functions with their docstrings and signatures\")\n) -> FaultyToolAnalysis {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python developer and software architect specializing in BIM (Building Information Modeling) systems.\n\n    Your task is to analyze a FAILED execution from COBBIE (a code-based BIM question-answering agent) to determine if the wrong answer was caused by a faulty helper function (tool).\n\n    EXECUTION CONTEXT:\n\n    Question Asked:\n    {{ question }}\n\n    Ground Truth (Correct Answer):\n    {{ ground_truth }}\n\n    Provided Answer (Wrong):\n    {{ provided_answer }}\n\n    Answer Verifier's Justification:\n    {{ justification }}\n\n    Execution History (thoughts, code, and results):\n    {{ history }}\n\n    Available Helper Functions:\n    {{ existing_helper_functions }}\n\n    YOUR ANALYSIS TASK:\n\n    Determine if the wrong answer was caused by a **faulty tool** (a helper function that returned incorrect results or behaved unexpectedly).\n\n    ANALYSIS CRITERIA:\n\n    A tool is FAULTY if:\n    1. **Incorrect Return Value**: The function returned wrong data (e.g., counted wrong elements, extracted wrong properties)\n    2. **Logic Error**: The function's implementation has a bug that causes incorrect behavior\n    3. **Edge Case Failure**: The function fails on specific inputs or model structures\n    4. **Parameter Handling Issue**: The function mishandles parameters or has incorrect assumptions\n    5. **Data Extraction Error**: The function extracts data from the IFC model incorrectly\n\n    A tool is NOT FAULTY if:\n    1. **Missing Tool**: No suitable tool exists (the system needs a NEW tool, not a fix to an existing one)\n    2. **Correct Tool, Wrong Usage**: Cobbie called the tool incorrectly (wrong parameters, wrong context)\n    3. **Reasoning Error**: Cobbie's logic or approach was flawed, not the tool itself\n    4. **Multiple Tool Issue**: Cobbie needed to use multiple tools but didn't\n    5. **Context/Prompt Issue**: Cobbie misunderstood the question or requirements\n    6. **Iteration Limit**: Cobbie ran out of iterations before completing the task\n\n    IMPORTANT GUIDELINES:\n\n    1. **Focus on Tool Behavior**: Examine what each tool RETURNED vs what it SHOULD have returned\n    2. **Compare with Ground Truth**: Check if tool outputs align with what's needed for the correct answer\n    3. **Trace Data Flow**: Follow how data from tools flowed through Cobbie's code\n    4. **Worst Offender**: If multiple tools are faulty, identify the PRIMARY/WORST one\n    5. **Be Conservative**: Only mark as faulty_tool if you have STRONG evidence the tool itself is broken\n    6. **Test Cases**: If faulty, provide SPECIFIC test cases that would demonstrate the failure\n\n    ANALYSIS PROCESS:\n\n    1. Review the execution history:\n       - What tools were called and with what parameters?\n       - What did each tool return?\n       - How did Cobbie use the tool outputs?\n\n    2. Compare tool outputs with ground truth:\n       - Given the ground truth answer, what should the tools have returned?\n       - Do the tool outputs contradict what's needed for correctness?\n\n    3. Identify the root cause:\n       - Is the tool implementation wrong?\n       - Or is this a usage issue, missing tool, or reasoning error?\n\n    4. If faulty tool identified:\n       - Name the specific tool\n       - Describe what's wrong (summary)\n       - Provide test cases that demonstrate the failure\n       - Assign confidence level\n\n    ERROR DESCRIPTION FORMAT (if faulty_tool is true):\n\n    Summary: [Brief 2-3 sentence description of what's wrong with the tool]\n\n    Test Cases:\n    - Test Case 1: [Describe inputs and expected vs actual behavior]\n    - Test Case 2: [Another test case demonstrating the failure]\n    - Test Case 3: [Optional third test case]\n\n    CONFIDENCE LEVELS:\n\n    - **high**: Clear evidence the tool is faulty, multiple indicators point to tool error\n    - **medium**: Strong suspicion the tool is faulty, but some ambiguity remains\n    - **low**: Possible tool fault, but could also be other factors\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test case 1: Faulty tool - function returns incorrect count\ntest FaultyToolPositiveTest {\n  functions [FaultyNewToolAnalysis]\n  args {\n    question \"How many doors have a fire rating of at least 30 minutes?\"\n    ground_truth \"There are 3 doors with a fire rating of at least 30 minutes.\"\n    provided_answer \"There are 15 doors with a fire rating of at least 30 minutes.\"\n    justification \"The system response contains incorrect numerical information. The ground truth states 3 doors, but the system reported 15. This is a significant discrepancy and represents a factual error.\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to count the doors. Let me use the available tool to count doors by type.\n\n      Code:\n      result = count_doors_by_fire_rating(path_ifc_model, min_fire_rating=30)\n      print(f\"Emergency exit doors: {result}\")\n\n      Result:\n      Emergency exit doors: 15\n\n      --- Final Answer ---\n      Thoughts: The count_doors_by_fire_rating function returned 15 doors with fire rating >= 30 minutes.\n      Answer: There are 15 doors with a fire rating of at least 30 minutes.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n\n      def count_doors_by_fire_rating(ifc_file_path: str, min_fire_rating: int) -> int:\n          '''Count doors that meet minimum fire rating requirements\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              min_fire_rating: Minimum fire rating in minutes\n\n          Returns:\n              Number of doors with fire rating >= min_fire_rating\n          '''\n    \"#\n  }\n}\n\n// Test case 2: Not a faulty tool - missing tool scenario\ntest FaultyToolNegativeTest_MissingTool {\n  functions [FaultyNewToolAnalysis]\n  args {\n    question \"What is the total thermal resistance (R-value) of the exterior walls?\"\n    ground_truth \"The total thermal resistance of the exterior walls is 4.5 m²K/W.\"\n    provided_answer \"I cannot determine the thermal resistance as the required property information is not directly available in the model.\"\n    justification \"The system abstained from providing a specific answer when ground truth shows a specific value should be calculable from the model data.\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to find thermal resistance properties of walls. Let me search for walls first.\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n      walls = model.by_type('IfcWall')\n      print(f\"Found {len(walls)} walls\")\n\n      Result:\n      Found 25 walls\n\n      --- Iteration 2 ---\n      Thoughts: I need to get thermal properties, but I don't have a tool for this. Let me try to find them manually.\n\n      Code:\n      for wall in walls[:3]:\n          psets = ifcopenshell.util.element.get_psets(wall)\n          print(f\"Wall {wall.GlobalId}: {psets}\")\n\n      Result:\n      Wall 2O2Fr$t4X7Zf8NOew3FL9r: {'Pset_WallCommon': {'ThermalTransmittance': 0.22}}\n      Wall 3P3Gs%u5Y8Ag9OPfx4GM0s: {'Pset_WallCommon': {'ThermalTransmittance': 0.22}}\n      Wall 4Q4Ht&v6Z9Bh0QPgy5HN1t: {'Pset_WallCommon': {'ThermalTransmittance': 0.22}}\n\n      --- Final Answer ---\n      Thoughts: I found thermal transmittance (U-value) but not R-value directly. I would need to calculate R = 1/U, but I'm not confident about handling all wall types correctly.\n      Answer: I cannot determine the thermal resistance as the required property information is not directly available in the model.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n\n      def get_element_properties(ifc_file_path: str, element_guid: str) -> dict:\n          '''Get all properties of a specific IFC element\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              element_guid: GlobalId of the element\n\n          Returns:\n              Dictionary of property sets and their values\n          '''\n    \"#\n  }\n}\n\n// Test case 3: Not a faulty tool - reasoning error by Cobbie\ntest FaultyToolNegativeTest_ReasoningError {\n  functions [FaultyNewToolAnalysis]\n  args {\n    question \"How many windows are on the north-facing facade?\"\n    ground_truth \"There are 8 windows on the north-facing facade.\"\n    provided_answer \"There are 24 windows on the north-facing facade.\"\n    justification \"The system response provides an incorrect count. The ground truth states 8 windows on the north facade, but the system reported 24, which appears to be counting all windows in the building rather than just north-facing ones.\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to count windows. Let me get all windows in the building.\n\n      Code:\n      windows = get_elements_by_type(path_ifc_model, 'IfcWindow')\n      print(f\"Total windows: {len(windows)}\")\n\n      Result:\n      Total windows: 24\n\n      --- Iteration 2 ---\n      Thoughts: I have the window count. Now I should filter by orientation, but I'm not sure how to determine north-facing. Let me just provide the total count.\n\n      Code:\n      # The model has 24 windows total\n      print(\"Windows found:\", len(windows))\n\n      Result:\n      Windows found: 24\n\n      --- Final Answer ---\n      Thoughts: I counted all windows in the building.\n      Answer: There are 24 windows on the north-facing facade.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n\n      def get_elements_by_type(ifc_file_path: str, ifc_type: str) -> list:\n          '''Get all elements of a specific IFC type\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              ifc_type: IFC element type (e.g., 'IfcWall', 'IfcWindow')\n\n          Returns:\n              List of IFC elements of the specified type\n          '''\n\n      def get_element_orientation(ifc_file_path: str, element_guid: str) -> str:\n          '''Get the orientation/facing direction of an element\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              element_guid: GlobalId of the element\n\n          Returns:\n              Orientation as compass direction (e.g., 'North', 'South', 'East', 'West')\n          '''\n    \"#\n  }\n}\n",
    "generators.baml": "// This helps use auto generate libraries you can use in the language of\n// your choice. You can have multiple generators if you use multiple languages.\n// Just ensure that the output_dir is different for each generator.\ngenerator target {\n    // Valid values: \"python/pydantic\", \"typescript\", \"ruby/sorbet\", \"rest/openapi\"\n    output_type \"python/pydantic\"\n\n    // Where the generated code will be saved (relative to baml_src/)\n    output_dir \"../\"\n\n    // The version of the BAML package you have installed (e.g. same version as your baml-py or @boundaryml/baml).\n    // The BAML VSCode extension version should also match this version.\n    version \"0.211.2\"\n\n    // Valid values: \"sync\", \"async\"\n    // This controls what `b.FunctionName()` will be (sync or async).\n    default_client_mode sync\n}\n",
    "identify_helper_function.baml": "// HelperFunctionIdentifier - Analyzes successful Cobbie executions to identify reusable helper functions\n// This agent extracts generalizable patterns from successful question-answering sessions\n// to build a library of high-level BIM/IFC analysis tools\n\nfunction HelperFunctionIdentifier(\n  history: string @description(\"Complete execution history from Cobbie: thoughts, code, results, and final answer\"),\n  example_question: string @description(\"The question that was successfully answered by Cobbie\"),\n  existing_helper_functions: string @description(\"List of all existing helper functions with their docstrings and signatures\")\n) -> NewToolAnalysis {\n  client GLM_4_6\n  prompt #\"\n    You are an expert Python developer and software architect specializing in BIM (Building Information Modeling) systems.\n\n    Your task is to analyze a successful execution from COBBIE (a code-based BIM question-answering agent) and determine if a reusable helper function should be extracted.\n\n    EXECUTION CONTEXT:\n\n    Question Answered:\n    {{ example_question }}\n\n    Execution History (thoughts, code, and results):\n    {{ history }}\n\n    Existing Helper Functions:\n    {{ existing_helper_functions }}\n\n    ENHANCEMENT VS CREATION DECISION:\n\n    Before recommending a new tool, check if an existing tool could be ENHANCED instead.\n\n    **Consider ENHANCEMENT (action=\"enhance_existing\") if:**\n    1. Existing tool provides 70%+ of needed functionality\n    2. Missing functionality can be added via optional parameters with sensible defaults\n    3. Enhancement maintains backward compatibility (existing code works unchanged)\n    4. Combined tool remains focused and understandable\n\n    **Choose CREATION (action=\"create_new\") if:**\n    1. No existing tool provides 70%+ overlap\n    2. Pattern is fundamentally different from existing tools\n    3. Enhancement would make existing tool too complex\n    4. New functionality is orthogonal to existing tools\n\n    **Choose NONE (action=\"none\") if:**\n    1. Existing tools already handle this adequately\n    2. Pattern is too specific to this question\n    3. Direct ifcopenshell calls are clearer\n\n    YOUR ANALYSIS CRITERIA:\n\n    A helper function SHOULD be created OR enhanced if:\n    1. **Generalizability**: Pattern applies to similar questions\n    2. **Abstraction Level**: Higher-level than direct ifcopenshell calls\n    3. **Reusability**: Multiple future questions could benefit\n    4. **Enhancement Opportunity**: Existing tool is close but missing one feature\n    5. **Clear Interface**: Clear parameters with sensible defaults\n    6. **Complexity Reduction**: It simplifies common BIM analysis tasks\n\n    A helper function SHOULD NOT be created if:\n    1. **Overfitting**: The code is too specific to this exact question or model\n    2. **Trivial**: It's just a simple wrapper around one ifcopenshell call\n    3. **Redundant**: An existing helper function already does this (or can easily be extended)\n    4. **Hard-coded values**: The code contains model-specific constants or assumptions\n    5. **One-off**: It's unlikely to be useful for other questions\n    6. **Too complex**: It combines unrelated operations that shouldn't be bundled together\n\n    ANALYSIS PROCESS:\n\n    1. Examine the execution history to identify:\n       - What ifcopenshell operations were used\n       - What patterns or logic were applied\n       - What intermediate results were computed\n       - What made this approach successful\n\n    2. Consider generalization:\n       - Can this pattern be abstracted to work with different IFC element types?\n       - Can it be parameterized to handle various filtering/sorting criteria?\n       - Does it represent a common BIM analysis operation?\n\n    3. Check against existing functions:\n       - Is there overlap with existing helper functions?\n       - Could an existing function be extended instead?\n\n    4. Define the helper function concept (if one should be created):\n       - Function name: Clear, descriptive, follows Python naming conventions\n       - Parameters: Generic, typed, well-defined\n       - Return type: Clear structure (list, dict, int, str, etc.)\n       - Purpose: Concise description of what it does and when to use it\n\n    IMPORTANT GUIDELINES:\n\n    - Prefer creating functions that encapsulate common BIM domain operations (e.g., \"get_elements_by_property\", \"calculate_total_area\")\n    - Avoid creating functions that are just thin wrappers (e.g., \"get_all_walls\" if it just calls model.by_type('IfcWall'))\n    - Focus on patterns that appeared necessary because ifcopenshell documentation queries were made\n    - Think about what would help COBBIE solve similar questions faster in the future\n\n    OUTPUT REQUIREMENTS:\n\n    1. Set `action` to \"create_new\", \"enhance_existing\", or \"none\"\n    2. For \"enhance_existing\":\n       - `tool_name` = existing tool to enhance\n       - `tool_description` = what parameters to add and how they extend functionality\n       - `existing_tool_for_enhancement` = same as tool_name\n    3. For \"create_new\":\n       - `tool_name` = new function name\n       - `tool_description` = full specification including parameters, return type, and use cases\n       - `existing_tool_for_enhancement` = null\n    4. For \"none\":\n       - `tool_name` = empty string\n       - `tool_description` = empty string\n       - `existing_tool_for_enhancement` = null\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// Test case for helper function identification with a clear reusable pattern\ntest HelperFunctionIdentifierPositiveTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"How many doors are on the ground floor?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to first understand how to filter elements by floor/storey in IFC. Let me search the documentation.\n\n      Code:\n      result = query_ifcopenshell_docs(\"filter elements by storey level\")\n\n      Result:\n      IfcRelContainedInSpatialStructure relates elements to spatial structures like storeys...\n\n      --- Iteration 2 ---\n      Thoughts: Now I'll get all doors and filter by the ground floor storey\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n\n      # Get ground floor storey\n      ground_floor = None\n      for storey in model.by_type('IfcBuildingStorey'):\n          if 'ground' in storey.Name.lower() or storey.Name == '0':\n              ground_floor = storey\n              break\n\n      # Get doors in ground floor\n      doors_on_ground = []\n      for rel in ground_floor.ContainsElements:\n          for element in rel.RelatedElements:\n              if element.is_a('IfcDoor'):\n                  doors_on_ground.append(element)\n\n      print(f\"Found {len(doors_on_ground)} doors on ground floor\")\n\n      Result:\n      Found 6 doors on ground floor\n\n      --- Final ---\n      Thoughts: Successfully identified all doors on the ground floor by traversing the spatial structure relationships.\n      Answer: There are 6 doors on the ground floor.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n    \"#\n  }\n}\n\n// Test case for a pattern that should NOT result in a helper function (too specific)\ntest HelperFunctionIdentifierNegativeTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"What is the height of wall with GlobalId '2O2Fr$t4X7Zf8NOew3FL9r'?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I need to find the specific wall by GlobalId and get its height\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n\n      wall = model.by_guid('2O2Fr$t4X7Zf8NOew3FL9r')\n      height = wall.Height\n\n      print(f\"Wall height: {height}\")\n\n      Result:\n      Wall height: 3.5\n\n      --- Final ---\n      Thoughts: Found the wall and extracted its height property directly.\n      Answer: The wall has a height of 3.5 meters.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n    \"#\n  }\n}\n\n// Test case with existing similar function (should not create duplicate)\ntest HelperFunctionIdentifierRedundantTest {\n  functions [HelperFunctionIdentifier]\n  args {\n    example_question \"How many windows are in the building?\"\n    history #\"\n      --- Iteration 1 ---\n      Thoughts: I'll count all windows in the model\n\n      Code:\n      import ifcopenshell\n      model = ifcopenshell.open(path_ifc_model)\n      windows = model.by_type('IfcWindow')\n      print(f\"Total windows: {len(windows)}\")\n\n      Result:\n      Total windows: 42\n\n      --- Final ---\n      Thoughts: Counted all window elements in the model.\n      Answer: There are 42 windows in the building.\n    \"#\n    existing_helper_functions #\"\n      def query_ifcopenshell_docs(query: str) -> str:\n          '''Search ifcopenshell documentation for information'''\n\n      def web_search(query: str) -> str:\n          '''Search the web for general information'''\n\n      def count_elements_by_type(ifc_file_path: str, ifc_type: str) -> int:\n          '''Count the number of elements of a specific IFC type in a model\n\n          Args:\n              ifc_file_path: Path to the IFC file\n              ifc_type: IFC element type (e.g., 'IfcWall', 'IfcWindow')\n\n          Returns:\n              int: Count of elements of the specified type\n          '''\n    \"#\n  }\n}\n",
    "schemas.baml": "// BAML schemas for BIM QA system\n\n// Code execution action (loop mode)\nclass CodeAction {\n  thoughts string @description(\"Reasoning for next step\")\n  python_code string @description(\"Code to execute\")\n}\n\n// Final answer action (completion mode)\nclass FinalAnswer {\n  thoughts string @description(\"Summary of findings\")\n  answer string @description(\"Final answer to user's question\")\n}\n\n// Tool creation result\nclass ToolCreationResult {\n  function_name string\n  function_implementation string\n  success bool\n}\n\n// Answer verification result\nclass SimilarityResult {\nsimilarity_score float\n  correct_answer bool\n  reasoning string\n}\n\n// Error analysis result\nclass ErrorAnalysisResult {\n  error_category string @description(\"faulty_tool, missing_tool, other\")\n  function_name string?\n  needs_new_tool bool\n}\n\n// Tool optimization result\nclass ToolOptimizationResult {\n  improvement string @description(\"create_new_tool, merge_existing_tools, update_existing_tool, no_action_needed\")\n  function_name string?\n  function_requirements string?\n  existing_tool_names string[]?\n}\n\n// Answer evaluation result\nclass AnswerEvaluationResult {\n  classification \"correct\" | \"wrong\" | \"abstained\" @description(#\"\n    Classification of the system response\n  \"#)\n\n  justification string @description(#\"\n    Brief explanation (2-3 sentences) of why this classification was chosen.\n  \"#)\n\n  confidence \"high\" | \"medium\" | \"low\" @description(#\"\n    Evaluator confidence level\n  \"#)\n}\n\n// Assessment result from ToolAssessor - tests function behavior without seeing implementation\nclass AssessmentResult {\n  assessment_status \"ok\" | \"needs_improvement\" @description(\"'ok' if function works as expected, 'needs_improvement' if issues found\")\n  assessment_details string @description(\"Detailed explanation of test results and any issues discovered\")\n  test_execution_log string? @description(\"Log of function execution and test cases attempted\")\n}\n\n// Extended result class for when tool creation is complete\nclass FunctionImplementation {\n  function_implementation string\n  confidence float?\n  needs_improvement bool\n}\n\n// Improved implementation from ToolCorrector - addresses assessment feedback\nclass ImprovedImplementation {\n  function_implementation string @description(\"Updated Python source code addressing assessment issues\")\n  reasoning string @description(\"Explanation of changes made and how they address the feedback\")\n  changes_summary string? @description(\"Brief summary of the main changes made\")\n}\n\n\n// Aligned question-answer pair for dataset cleaning\nclass AlignedQAPair {\n  thought string @description(\"Analysis of the alignment between question and answer, and reasoning for any changes\")\n  aligned_question string @description(\"Question reformulated to align with answer structure and scope (or original if already aligned)\")\n  aligned_answer string @description(\"Answer with improved formatting/clarity while preserving factual content (or original if already good)\")\n  was_modified bool @description(\"Whether any modifications were made to question or answer\")\n}\n\n// Successful outcome - function has been tested and improved successfully\nclass TestAndImproveSuccess {\n  function_implementation string @description(\"Final validated function implementation\")\n  assessment_details string @description(\"Final assessment confirming function works correctly\")\n  iterations_used int @description(\"Number of iterations needed to achieve success\")\n  total_time_seconds float @description(\"Total time taken for testing and improvement\")\n}\n\n// Error outcome - testing and improvement process failed\nclass TestAndImproveError {\n  error_message string @description(\"Detailed error description\")\n  iterations_completed int @description(\"Number of iterations completed before failure\")\n  final_assessment_status string? @description(\"Last known assessment status, if any\")\n  partial_function_implementation string? @description(\"Best function implementation achieved, if any\")\n}\n\n// Category validation result for question-answer pairs\nclass CategoryValidationResult {\n  validated_category string @description(\"The correct category (1, 2, 3, or 4) according to the taxonomy\")\n  updated bool @description(\"Whether the category was changed from the original\")\n  thought string @description(\"Reasoning for the category classification and any changes made\")\n}\n\n// Helper function identification result from successful Cobbie executions\nclass NewToolAnalysis {\n  thoughts string @description(\"Step-by-step analysis of the execution history to identify reusable patterns\")\n\n  action \"create_new\" | \"enhance_existing\" | \"none\" @description(#\"\n    Decision on tool management:\n    - create_new: Create a completely new helper function\n    - enhance_existing: Enhance existing tool with optional parameters\n    - none: No tool creation or enhancement needed\n  \"#)\n\n  tool_name string @description(#\"\n    For create_new: Name for new function\n    For enhance_existing: Name of existing tool to enhance\n    For none: Empty string\n  \"#)\n\n  tool_description string @description(#\"\n    For create_new: Full function specification\n    For enhance_existing: Enhancement description (what parameters to add)\n    For none: Empty string\n  \"#)\n\n  existing_tool_for_enhancement string? @description(#\"\n    Only for enhance_existing: Name of tool to enhance (same as tool_name)\n  \"#)\n}\n\n// Helper function implementation result - final output from HelperFunctionCreator\nclass NewHelperFunction {\n  thoughts string @description(\"Summary of development process, testing performed, and validation results\")\n  function_implementation string @description(\"Complete Python function implementation including imports, docstring, and type hints\")\n  success bool @description(\"Whether the function is complete, tested, and ready for use\")\n}\n\n// Faulty tool identification result - analyzes wrong answers to identify tool-related failures\nclass FaultyToolAnalysis {\n  thoughts string @description(\"Chain-of-thought analysis of the execution history to identify tool-related failures\")\n  faulty_tool bool @description(\"Whether a faulty tool was identified as the primary cause of the wrong answer\")\n  faulty_tool_name string @description(\"Name of the faulty tool (empty string if faulty_tool is false)\")\n  error_description string @description(\"Summary of the error and test cases demonstrating the failure (empty string if faulty_tool is false)\")\n  confidence \"high\" | \"medium\" | \"low\" @description(\"Confidence level in this faulty tool identification\")\n}\n\n// Tool fixing result - analyzes and fixes faulty helper functions\nclass UpdatedHelperFunction {\n  thoughts string @description(\"Analysis of the faulty function and explanation of the fixing process\")\n  fixed_implementation string @description(\"Fixed Python function implementation that addresses the identified issues\")\n  changes_summary string @description(\"Summary of the main changes made to fix the function\")\n  success bool @description(\"Whether the function was successfully fixed and is ready for use\")\n  test_cases_provided string @description(\"Test cases that can be used to verify the fix works correctly\")\n}\n\n// Helper function usage assessment - analyzes if a specific tool was helpful during execution\nclass HelperFunctionAssessment {\n  thoughts string @description(\"Detailed analysis of how the tool was used during execution\")\n\n  tool_was_used bool @description(\"Whether the tool was actually called during execution\")\n\n  tool_usage_quality \"helpful\" | \"not_used\" | \"ignored\" | \"misused\" | \"harmful\" @description(#\"\n    Assessment of how the tool contributed to the answer:\n    - helpful: Tool was used correctly and contributed to producing the correct answer\n    - not_used: Tool was available but Cobbie didn't use it at all\n    - ignored: Tool was considered/mentioned but deemed unnecessary or not applicable\n    - misused: Tool was used incorrectly (wrong parameters, wrong context, misunderstood purpose)\n    - harmful: Tool was used and led to incorrect results or wrong reasoning\n  \"#)\n\n  usage_details string @description(#\"\n    Detailed explanation of tool usage patterns and outcomes:\n    - If helpful: How the tool contributed to the correct answer\n    - If not_used: Why the tool wasn't needed or what alternative approach was used\n    - If ignored: Why Cobbie chose not to use it\n    - If misused: What parameters were wrong or how the usage was incorrect\n    - If harmful: How the tool's output led to the wrong answer\n  \"#)\n\n  recommendation \"keep_tool\" | \"discard_tool\" | \"improve_tool\" | \"unclear\" @description(#\"\n    Final recommendation based on usage analysis:\n    - keep_tool: Tool was helpful and should be saved permanently\n    - discard_tool: Tool wasn't useful, was harmful, or is redundant\n    - improve_tool: Tool has potential but needs fixes or refinement\n    - unclear: Insufficient evidence to make a confident decision (need more test cases)\n  \"#)\n\n  confidence \"high\" | \"medium\" | \"low\" @description(#\"\n    Confidence level in this assessment:\n    - high: Clear evidence from execution history supports the assessment\n    - medium: Strong indicators but some ambiguity or edge cases\n    - low: Limited evidence or conflicting signals\n  \"#)\n}\n",
}

